import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                return buflen > 0;
            }
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
            return hasNextByte();
        }

        public int nextInt() {
            if (!hasNext()) throw new RuntimeException("No more input");
            int n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    n = n * 10 + (b - '0');
                } else {
                    return minus ? -n : n;
                }
                b = readByte();
            }
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int u = scanner.nextInt();

        List<Integer>[] numToCards = new ArrayList[u + 1];
        for (int i = 1; i <= u; i++) {
            numToCards[i] = new ArrayList<>();
        }

        int[] remaining = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            remaining[i] = k;
            for (int j = 0; j < k; j++) {
                int val = scanner.nextInt();
                numToCards[val].add(i);
            }
        }

        List<Integer> winners = new ArrayList<>();
        for (int step = 0; step < u; step++) {
            int drawn = scanner.nextInt();
            if (!winners.isEmpty()) {
                continue;
            }

            for (int card : numToCards[drawn]) {
                remaining[card]--;
                if (remaining[card] == 0) {
                    winners.add(card);
                }
            }
        }

        winners.sort(null);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < winners.size(); i++) {
            if (i > 0) sb.append(" ");
            sb.append(winners.get(i));
        }
        System.out.println(sb.toString());
    }
}
